local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Keybinds ported from the old KoolDots setup (JadeJitsu/MyHyprlandDotfiles configs/Keybinds.conf).
-- Script-based entries (rofi, waybar, swaync, wallust) are mapped to their DMS equivalents or dropped.
local function dms(call) return hl.dsp.exec_cmd("dms ipc call " .. call) end
local function layout(name) return function() hl.config({ general = { layout = name } }) end end

-- Apps and launchers
hl.bind(mainMod .. " + RETURN",         hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E",              hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + B",              hl.dsp.exec_cmd('xdg-open "https://"'))
hl.bind(mainMod .. " + D",              dms("spotlight toggle"))
hl.bind(mainMod .. " + A",              dms("hypr toggleOverview"))
hl.bind(mainMod .. " + H",              dms("hypr toggleBinds"))
hl.bind(mainMod .. " + SHIFT + K",      dms("hypr toggleBinds"))
hl.bind(mainMod .. " + SHIFT + E",      dms("settings toggle"))
hl.bind(mainMod .. " + SHIFT + N",      dms("notifications toggle"))
hl.bind(mainMod .. " + N",              dms("night toggle"))
hl.bind(mainMod .. " + T",              dms("theme toggle"))
hl.bind(mainMod .. " + ALT + V",        dms("clipboard toggle"))
hl.bind(mainMod .. " + ESCAPE",         dms("processlist toggle"))
hl.bind("CTRL + ALT + W",               dms("wallpaper next"))
hl.bind("CTRL + ALT + L",               dms("lock lock"))
hl.bind("CTRL + ALT + P",               dms("powermenu toggle"))
hl.bind("CTRL + ALT + Delete",          hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))

-- Window management
hl.bind(mainMod .. " + Q",              hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + Q",      hl.dsp.window.kill())
hl.bind(mainMod .. " + F",              hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + SHIFT + F",      hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + CTRL + F",       hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mainMod .. " + SPACE",          hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + P",              hl.dsp.window.pseudo())
hl.bind("ALT + Tab", function()
    hl.dispatch(hl.dsp.window.cycle_next())
    hl.dispatch(hl.dsp.window.bring_to_top())
end)

-- Layouts
hl.bind(mainMod .. " + ALT + 1",        layout("dwindle"))
hl.bind(mainMod .. " + ALT + 2",        layout("master"))
hl.bind(mainMod .. " + ALT + 3",        layout("scrolling"))
hl.bind(mainMod .. " + ALT + 4",        layout("monocle"))
hl.bind(mainMod .. " + CTRL + D",       hl.dsp.layout("removemaster"))
hl.bind(mainMod .. " + I",              hl.dsp.layout("addmaster"))
hl.bind(mainMod .. " + J",              hl.dsp.layout("cyclenext"))
hl.bind(mainMod .. " + K",              hl.dsp.layout("cycleprev"))
hl.bind(mainMod .. " + CTRL + RETURN",  hl.dsp.layout("swapwithmaster"))
hl.bind(mainMod .. " + SHIFT + I",      hl.dsp.layout("togglesplit"))
hl.bind(mainMod .. " + SHIFT + period", hl.dsp.layout("move +col"))
hl.bind(mainMod .. " + SHIFT + comma",  hl.dsp.layout("move -col"))
hl.bind(mainMod .. " + ALT + comma",    hl.dsp.layout("swapcol l"))
hl.bind(mainMod .. " + ALT + period",   hl.dsp.layout("swapcol r"))

-- Groups
hl.bind(mainMod .. " + G",              hl.dsp.group.toggle())
hl.bind(mainMod .. " + CTRL + Tab",     hl.dsp.group.next())
hl.bind(mainMod .. " + CTRL + K",       hl.dsp.window.move({ into_group = "left" }))
hl.bind(mainMod .. " + CTRL + L",       hl.dsp.window.move({ into_group = "right" }))
hl.bind(mainMod .. " + CTRL + H",       hl.dsp.window.move({ out_of_group = true }))

-- Focus, move, swap, resize
for dir, key in pairs({ left = "left", right = "right", up = "up", down = "down" }) do
    hl.bind(mainMod .. " + " .. key,                hl.dsp.focus({ direction = dir }))
    hl.bind(mainMod .. " + CTRL + " .. key,         hl.dsp.window.move({ direction = dir }))
    hl.bind(mainMod .. " + ALT + " .. key,          hl.dsp.window.swap({ direction = dir }))
end
hl.bind(mainMod .. " + SHIFT + left",   hl.dsp.window.resize({ x = -50, y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + right",  hl.dsp.window.resize({ x = 50,  y = 0,   relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + up",     hl.dsp.window.resize({ x = 0,   y = -50, relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + down",   hl.dsp.window.resize({ x = 0,   y = 50,  relative = true }), { repeating = true })

-- Workspaces
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,                hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key,        hl.dsp.window.move({ workspace = i }))
    hl.bind(mainMod .. " + CTRL + " .. key,         hl.dsp.window.move({ workspace = i, follow = false }))
end
hl.bind(mainMod .. " + SHIFT + bracketleft",  hl.dsp.window.move({ workspace = "-1" }))
hl.bind(mainMod .. " + SHIFT + bracketright", hl.dsp.window.move({ workspace = "+1" }))
hl.bind(mainMod .. " + CTRL + bracketleft",   hl.dsp.window.move({ workspace = "-1", follow = false }))
hl.bind(mainMod .. " + CTRL + bracketright",  hl.dsp.window.move({ workspace = "+1", follow = false }))
hl.bind(mainMod .. " + Tab",            hl.dsp.focus({ workspace = "m+1" }))
hl.bind(mainMod .. " + SHIFT + Tab",    hl.dsp.focus({ workspace = "m-1" }))
hl.bind(mainMod .. " + period",         hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + comma",          hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + mouse_down",     hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",       hl.dsp.focus({ workspace = "e-1" }))
-- Activities (KDE-style context switching): Super+W toggles between the
-- "work" (ws 1-4) and "personal" (ws 5-8) workspace groups.
-- See scripts/activity-switch.sh for the activity definitions.
hl.bind(mainMod .. " + W",              hl.dsp.exec_cmd("~/.config/hypr/scripts/activity-switch.sh next"))

hl.bind(mainMod .. " + U",              hl.dsp.workspace.toggle_special("special"))
hl.bind(mainMod .. " + SHIFT + U",      hl.dsp.window.move({ workspace = "special:special" }))
hl.bind(mainMod .. " + CTRL + F9",      hl.dsp.workspace.move({ monitor = "l" }))
hl.bind(mainMod .. " + CTRL + F10",     hl.dsp.workspace.move({ monitor = "r" }))
hl.bind(mainMod .. " + CTRL + F11",     hl.dsp.workspace.move({ monitor = "u" }))
hl.bind(mainMod .. " + CTRL + F12",     hl.dsp.workspace.move({ monitor = "d" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Screenshots (saved to file and copied to clipboard)
hl.bind("Print",                 hl.dsp.exec_cmd("dms screenshot full"))
hl.bind(mainMod .. " + Print",   hl.dsp.exec_cmd("dms screenshot region"))

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
